/**
 * Resolves the app's real page addresses for rows the service layer only
 * knows by id. Every href stored on a notification or returned with a search
 * hit is built here through `@/lib/url`, so it always matches a served route.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

async function orgSlugFor(orgId: OrgId): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? null;
}

/** `/acme` — the fallback when the subject has gone missing. */
export async function orgHref(orgId: OrgId): Promise<string> {
  const slug = await orgSlugFor(orgId);
  return slug === null ? "/" : orgPath(slug);
}

export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const slug = await orgSlugFor(orgId);
  return slug === null ? "/" : settingsPath(slug, section);
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const slug = await orgSlugFor(orgId);
  if (slug === null) return "/";

  const project = await projectRepo.findProjectById(orgId, projectId);
  return project ? projectPath(slug, project.slug) : orgPath(slug);
}

export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string> {
  const slug = await orgSlugFor(orgId);
  if (slug === null) return "/";

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(slug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project ? issuePath(slug, project.slug, issue.number) : orgPath(slug);
}

/** A comment has no page of its own; it lives on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  return comment ? issueHref(orgId, comment.issueId) : orgHref(orgId);
}

