import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as ns from "@/server/services/notification-service";
import * as searchService from "@/server/services/search-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("tmpchk", "free");
  const list = (who: keyof typeof t.actors) => ns.listNotifications(t.actors[who], { orgId: t.org.id, recipientId: t.userIds[who], unreadOnly: false, limit: 100, cursor: null });
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Findme", assigneeId: t.userIds.admin }));
  await issueService.moveIssue(t.actors.member, { orgId: t.org.id, issueId: issue.id, toStatus: "done", toIndex: 0 } as never);
  console.log((await list("admin")).items.map((n) => [n.kind, n.href]));
  await expect(ns.listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, limit: 10, cursor: null })).rejects.toThrow();
  for (let i = 0; i < 3; i++) await projectService.createProject(t.actors.member, { orgId: t.org.id, name: "P" + i, slug: "p" + i, key: "P" + i, description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null }).catch((e) => console.log("refused", e.message));
  await usageService.recomputeUsage(t.org.id);
  console.log((await list("owner")).items.map((n) => [n.kind, n.title, n.href]));
  console.log(await ns.markAllRead(t.actors.owner, t.org.id), (await list("admin")).items.filter((n) => n.readAt === null).length);
  const hits = await searchService.search(t.actors.member, { orgId: t.org.id, q: "Findme", limit: 10, cursor: null } as never);
  console.log(hits.items.map((h) => h.href));
});
EOF
